-- Functions (deferred)
CREATE OR REPLACE FUNCTION public._fp_fire_push_notification(p_event_type text, p_job fp_jobs, p_actor text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_url     text := 'https://egztpclpcnizcdtfugsv.supabase.co/functions/v1/send-field-push';
  v_payload jsonb;
  v_request_id bigint;
BEGIN
  -- Skip push if no crew assigned (nothing to notify)
  IF p_job.crew IS NULL OR p_job.crew = '' THEN
    RETURN;
  END IF;

  v_payload := jsonb_build_object(
    'event',              p_event_type,
    'fp_job_id',          p_job.id,
    'title',              p_job.title,
    'status',             p_job.status,
    'priority',           p_job.priority,
    'zone',               p_job.zone,
    'crew',               p_job.crew,
    'previous_crew',      p_job.previous_crew,
    'customer_name',      p_job.customer_name,
    'company_name',       p_job.company_name,
    'address',            p_job.address,
    'parish',             p_job.parish,
    'latitude',           p_job.latitude,
    'longitude',          p_job.longitude,
    'bandwidth_required', p_job.bandwidth_required,
    'service_type',       p_job.service_type,
    'satellite_image_url',p_job.satellite_image_url,
    'street_view_url',    p_job.street_view_url,
    'source_quote_id',    p_job.source_quote_id,
    'actor',              p_actor,
    'reason',             p_reason,
    'timestamp',          now()
  );

  -- Fire-and-forget to send-field-push (verify_jwt=false, so no auth header needed)
  BEGIN
    SELECT net.http_post(
      url     := v_url,
      body    := v_payload,
      headers := jsonb_build_object('Content-Type','application/json')
    ) INTO v_request_id;
  EXCEPTION WHEN OTHERS THEN
    -- Never let push failure break the dispatch transaction
    RAISE WARNING 'fp push notification failed (non-blocking): %', SQLERRM;
  END;
END;
$function$
;

CREATE OR REPLACE FUNCTION public.get_latest_session_journal()
 RETURNS SETOF session_journal
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT * FROM public.session_journal
  ORDER BY ended_at DESC
  LIMIT 1;
$function$
;

CREATE OR REPLACE FUNCTION public.search_system_events(p_event_type text DEFAULT NULL::text, p_severity text DEFAULT NULL::text, p_platform text DEFAULT NULL::text, p_since timestamp with time zone DEFAULT (now() - '7 days'::interval), p_until timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 100)
 RETURNS SETOF system_events
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select * from system_events
  where created_at between p_since and p_until
    and (p_event_type is null or event_type ilike '%'||p_event_type||'%')
    and (p_severity is null or severity = p_severity)
    and (p_platform is null or platform = p_platform)
  order by created_at desc
  limit p_limit;
$function$
;

CREATE OR REPLACE FUNCTION public.search_audit_log(p_table_name text DEFAULT NULL::text, p_operation text DEFAULT NULL::text, p_actor_email text DEFAULT NULL::text, p_since timestamp with time zone DEFAULT (now() - '7 days'::interval), p_until timestamp with time zone DEFAULT now(), p_limit integer DEFAULT 100)
 RETURNS SETOF audit_log
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
  select * from audit_log
  where occurred_at between p_since and p_until
    and (p_table_name is null or table_name = p_table_name)
    and (p_operation is null or operation = p_operation)
    and (p_actor_email is null or actor_email ilike '%'||p_actor_email||'%')
  order by occurred_at desc
  limit p_limit;
$function$
;

-- Views
CREATE OR REPLACE VIEW public.leaderboard_rankings AS
 SELECT ts.technician_email,
    ts.technician_name,
    ts.level,
    ts.xp_earned,
    ts.metres_completed,
    ts.metres_target,
    ts.jobs_completed,
    ts.jobs_target,
    ts.scans_completed,
    ts.first_time_pass_rate,
    ts.streak_days,
    ts.badges,
    ts.date,
    round((ts.metres_completed / NULLIF(ts.metres_target, 0::double precision) * 100::double precision)::numeric, 1) AS metres_pct,
    round(ts.jobs_completed::numeric / NULLIF(ts.jobs_target, 0)::numeric * 100::numeric, 1) AS jobs_pct,
    rank() OVER (PARTITION BY ts.date ORDER BY ts.xp_earned DESC) AS daily_rank,
    COALESCE(ttl.completed, false) AS training_complete
   FROM technician_stats ts
     LEFT JOIN technician_training_logs ttl ON ts.technician_email = ttl.technician_email AND ttl.completed = true
  ORDER BY ts.xp_earned DESC;
CREATE OR REPLACE VIEW public.speed_by_parish AS
 SELECT parish,
    count(*) AS sample_size,
    round(avg(download_mbps), 2) AS avg_download_mbps,
    round(avg(upload_mbps), 2) AS avg_upload_mbps,
    round(avg(latency_ms), 2) AS avg_latency_ms,
    round(percentile_disc(0.5::double precision) WITHIN GROUP (ORDER BY download_mbps), 2) AS median_download_mbps,
    round(percentile_disc(0.95::double precision) WITHIN GROUP (ORDER BY download_mbps), 2) AS p95_download_mbps
   FROM speed_test_history
  WHERE tested_at > (now() - '7 days'::interval) AND parish IS NOT NULL
  GROUP BY parish
 HAVING count(*) >= 5;
CREATE OR REPLACE VIEW public.v_public_incidents AS
 SELECT id,
    type,
    severity,
    title,
    city,
    affected_parish,
    customer_summary AS summary,
    status,
    created_at,
    updated_at,
    first_alarm_at AS started_at,
    resolved_at,
    estimated_resolution_at,
    affected_customers,
        CASE severity
            WHEN 'outage'::text THEN 3
            WHEN 'degraded'::text THEN 2
            WHEN 'planned'::text THEN 1
            ELSE 0
        END AS severity_rank
   FROM network_incidents
  WHERE resolved_at IS NULL OR resolved_at >= (now() - '7 days'::interval);
CREATE OR REPLACE VIEW public.v_predicted_incidents AS
 WITH incident_assets AS (
         SELECT DISTINCT ni.id AS incident_id,
            ni.title AS incident_title,
            ni.severity AS incident_severity,
            ni.first_alarm_at,
            ni.created_at AS incident_created_at,
            ni.resolved_at,
            a.asset_id
           FROM network_incidents ni
             JOIN alarms a ON a.primary_incident_id = ni.id AND a.asset_id IS NOT NULL
        ), pre_incident_wos AS (
         SELECT ia.incident_id,
            ia.incident_title,
            ia.incident_severity,
            ia.first_alarm_at,
            ia.incident_created_at,
            ia.resolved_at,
            ia.asset_id,
            wo.id AS predictive_wo_id,
            wo.reference AS predictive_wo_ref,
            wo.created_at AS wo_drafted_at,
            wo.priority AS wo_priority,
            wo.status AS wo_status,
            wo.triggering_score,
            EXTRACT(epoch FROM ia.first_alarm_at - wo.created_at) / 3600.0 AS lead_time_hours
           FROM incident_assets ia
             LEFT JOIN work_orders wo ON wo.triggering_asset_id = ia.asset_id AND wo.source_kind = 'predictive_maintenance'::text AND wo.created_at < ia.first_alarm_at AND wo.created_at > (ia.first_alarm_at - '60 days'::interval)
        )
 SELECT incident_id,
    incident_title,
    incident_severity,
    first_alarm_at,
    incident_created_at,
    resolved_at,
    asset_id,
    predictive_wo_id,
    predictive_wo_ref,
    wo_drafted_at,
    wo_priority,
    wo_status,
    triggering_score,
    round(lead_time_hours, 1) AS lead_time_hours,
        CASE
            WHEN predictive_wo_id IS NULL THEN 'missed'::text
            WHEN wo_status = 'completed'::text AND wo_drafted_at < (first_alarm_at - '04:00:00'::interval) THEN 'caught_acted'::text
            WHEN wo_status = 'rejected'::text THEN 'caught_dismissed'::text
            WHEN wo_status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'dispatched'::text, 'approved'::text, 'validated'::text, 'validation_pending'::text, 'evidence_required'::text]) THEN 'caught_unacted'::text
            ELSE 'caught_other'::text
        END AS prediction_outcome
   FROM pre_incident_wos;
CREATE OR REPLACE VIEW public.v_public_predictive_kpi AS
 WITH last_30d AS (
         SELECT sum(
                CASE
                    WHEN v_predicted_incidents.prediction_outcome = 'caught_acted'::text THEN 1
                    ELSE 0
                END) AS caught_and_prevented,
            sum(
                CASE
                    WHEN v_predicted_incidents.prediction_outcome = ANY (ARRAY['caught_acted'::text, 'caught_unacted'::text, 'caught_dismissed'::text]) THEN 1
                    ELSE 0
                END) AS caught_total,
            count(DISTINCT v_predicted_incidents.incident_id) AS total_incidents,
            avg(v_predicted_incidents.lead_time_hours) FILTER (WHERE v_predicted_incidents.prediction_outcome = 'caught_acted'::text) AS avg_lead_time_hours
           FROM v_predicted_incidents
          WHERE v_predicted_incidents.incident_created_at > (now() - '30 days'::interval)
        ), monitoring AS (
         SELECT count(*) AS currently_monitored
           FROM network_assets
          WHERE network_assets.status = 'active'::text
        ), recently_flagged AS (
         SELECT count(DISTINCT asset_health_scores.asset_id) AS flagged_count
           FROM asset_health_scores
          WHERE asset_health_scores.computed_at > (now() - '7 days'::interval) AND asset_health_scores.score < 0.30
        )
 SELECT COALESCE(l.caught_and_prevented, 0::bigint) AS caught_and_prevented_30d,
    COALESCE(l.caught_total, 0::bigint) AS caught_total_30d,
    COALESCE(l.total_incidents, 0::bigint) AS total_incidents_30d,
        CASE
            WHEN l.total_incidents > 0 THEN round(l.caught_and_prevented::numeric / l.total_incidents::numeric * 100::numeric, 1)
            ELSE NULL::numeric
        END AS catch_and_prevent_rate_pct,
    round(l.avg_lead_time_hours, 1) AS avg_lead_time_hours,
    m.currently_monitored,
    r.flagged_count AS currently_flagged
   FROM last_30d l,
    monitoring m,
    recently_flagged r;
CREATE OR REPLACE VIEW public.v_cron_heartbeat AS
 WITH last_runs AS (
         SELECT j.jobname,
            j.schedule,
            j.active,
            ( SELECT d.start_time
                   FROM cron.job_run_details d
                  WHERE d.jobid = j.jobid
                  ORDER BY d.start_time DESC
                 LIMIT 1) AS last_run_at,
            ( SELECT d.status
                   FROM cron.job_run_details d
                  WHERE d.jobid = j.jobid
                  ORDER BY d.start_time DESC
                 LIMIT 1) AS last_status,
            ( SELECT count(*) AS count
                   FROM cron.job_run_details d
                  WHERE d.jobid = j.jobid AND d.start_time > (now() - '24:00:00'::interval)) AS runs_last_24h,
            ( SELECT count(*) AS count
                   FROM cron.job_run_details d
                  WHERE d.jobid = j.jobid AND d.start_time > (now() - '24:00:00'::interval) AND d.status = 'succeeded'::text) AS success_last_24h,
            ( SELECT count(*) AS count
                   FROM cron.job_run_details d
                  WHERE d.jobid = j.jobid AND d.start_time > (now() - '24:00:00'::interval) AND d.status = 'failed'::text) AS fail_last_24h,
                CASE
                    WHEN j.schedule ~ '^\* \* \* \* \*$'::text THEN '00:05:00'::interval
                    WHEN j.schedule ~ '^\*/[0-9]+ \* \* \* \*$'::text THEN '00:30:00'::interval
                    WHEN j.schedule ~ '^[0-9]+ \* \* \* \*$'::text THEN '02:00:00'::interval
                    WHEN j.schedule ~ '^[0-9]+ [0-9]+ \* \* \*$'::text THEN '36:00:00'::interval
                    WHEN j.schedule ~ '\* \* \* \*$'::text THEN '7 days'::interval
                    ELSE '12:00:00'::interval
                END AS stale_threshold,
                CASE
                    WHEN j.schedule = '* * * * *'::text THEN '00:05:00'::interval
                    WHEN j.schedule ~~ '*/30 %'::text THEN '01:30:00'::interval
                    WHEN j.schedule ~~ '*/15 %'::text THEN '00:45:00'::interval
                    WHEN j.schedule ~~ '*/5 %'::text THEN '00:20:00'::interval
                    WHEN j.schedule ~~ '*/1 %'::text OR j.schedule = '* * * * *'::text THEN '00:05:00'::interval
                    ELSE NULL::interval
                END AS precise_threshold
           FROM cron.job j
        )
 SELECT jobname,
    schedule,
    active,
    last_run_at,
    last_status,
    runs_last_24h,
    success_last_24h,
    fail_last_24h,
        CASE
            WHEN NOT active THEN 'disabled'::text
            WHEN last_run_at IS NULL THEN 'never_ran'::text
            WHEN last_run_at < (now() - COALESCE(precise_threshold, stale_threshold)) THEN 'stale'::text
            WHEN fail_last_24h > 0 AND runs_last_24h > 0 AND (fail_last_24h::double precision / runs_last_24h::double precision) > 0.3::double precision THEN 'failing'::text
            WHEN last_status = 'failed'::text THEN 'last_failed'::text
            ELSE 'healthy'::text
        END AS health
   FROM last_runs
  ORDER BY (
        CASE
            WHEN NOT active THEN 3
            WHEN last_run_at IS NULL THEN 2
            ELSE 1
        END), last_run_at DESC NULLS LAST;
CREATE OR REPLACE VIEW public.v_recent_migrations AS
 SELECT version,
    name,
    to_timestamp("left"(version, 10)::bigint::double precision) AS applied_at_estimate
   FROM supabase_migrations.schema_migrations
  ORDER BY version DESC
 LIMIT 50;
CREATE OR REPLACE VIEW public.v_table_sizes AS
 SELECT schemaname,
    relname AS table_name,
    pg_size_pretty(pg_total_relation_size(relid::regclass)) AS total_size,
    pg_total_relation_size(relid::regclass) AS total_size_bytes,
    n_live_tup AS live_rows,
    n_dead_tup AS dead_rows
   FROM pg_stat_user_tables
  WHERE schemaname = 'public'::name
  ORDER BY (pg_total_relation_size(relid::regclass)) DESC
 LIMIT 50;
CREATE OR REPLACE VIEW public.v_network_assets AS
 SELECT na.id,
    na.asset_ref,
    na.asset_type,
    na.status,
    na.address,
    na.property_address,
    na.road_snap_name,
    na.customer_reference,
    na.health_score,
    na.installed_date,
    na.latitude,
    na.longitude,
    na.tenant_id,
    t.name AS tenant_name,
    na.created_at,
    na.updated_at
   FROM network_assets na
     LEFT JOIN tenants t ON t.id = na.tenant_id;
CREATE OR REPLACE VIEW public.customer_360 AS
 SELECT cp.user_id,
    cp.full_name,
    cp.phone,
    cp.address,
    cp.region,
    cp.plan_name,
    cp.plan_speed,
    cp.plan_price,
    cp.plan_status,
    cp.account_id,
    cp.referral_code,
    s.id AS subscription_id,
    s.plan_type,
    s.speed_down_mbps,
    s.speed_up_mbps,
    s.monthly_price_usd,
    s.billing_cycle,
    s.next_billing_date,
    s.status AS sub_status,
    ( SELECT count(*)::integer AS count
           FROM support_tickets st
          WHERE st.user_id = cp.user_id AND st.status = 'open'::text) AS open_tickets,
    ( SELECT min(b.due_date) AS min
           FROM customer_bills b
          WHERE b.user_id = cp.user_id AND b.status <> 'paid'::text) AS next_payment_due,
    ( SELECT sum(b.amount) AS sum
           FROM customer_bills b
          WHERE b.user_id = cp.user_id AND b.status <> 'paid'::text) AS total_outstanding,
    cp.created_at AS customer_since
   FROM customer_profiles cp
     LEFT JOIN customers c ON c.email IS NOT NULL AND lower(c.email) = (( SELECT lower(p.email) AS lower
           FROM profiles p
          WHERE p.id = cp.user_id))
     LEFT JOIN subscriptions s ON s.customer_id = c.id;
CREATE OR REPLACE VIEW public.customer_lifecycle AS
 SELECT cp.user_id,
    cp.full_name,
    cp.phone,
    cp.region AS parish,
    c.id AS customer_id,
    c.email,
    c.customer_name,
    c.created_at AS signed_up_at,
    s.id AS subscription_id,
    s.plan_type,
    s.speed_down_mbps,
    s.speed_up_mbps,
    s.monthly_price_usd,
    s.promo_price_usd,
    s.promo_ends_at,
    s.status AS subscription_status,
    s.next_billing_date,
    ( SELECT count(*) AS count
           FROM invoices
          WHERE invoices.customer_id = c.id) AS total_invoices,
    ( SELECT count(*) AS count
           FROM invoices
          WHERE invoices.customer_id = c.id AND invoices.status = 'paid'::text) AS paid_invoices,
    ( SELECT COALESCE(sum(payments.amount_usd), 0::numeric) AS "coalesce"
           FROM payments
          WHERE payments.customer_id = c.id AND payments.status = 'succeeded'::text) AS lifetime_paid_usd,
    ( SELECT count(*) AS count
           FROM support_tickets
          WHERE s.customer_id = c.id) AS total_tickets,
    ( SELECT count(*) AS count
           FROM support_tickets
          WHERE s.customer_id = c.id AND (support_tickets.status = ANY (ARRAY['open'::text, 'investigating'::text]))) AS open_tickets,
    ( SELECT count(*) AS count
           FROM speed_test_history
          WHERE speed_test_history.user_id = cp.user_id) AS speed_tests_run,
    ( SELECT max(speed_test_history.download_mbps) AS max
           FROM speed_test_history
          WHERE speed_test_history.user_id = cp.user_id) AS peak_download_mbps,
    ( SELECT count(*) AS count
           FROM referrals
          WHERE referrals.referrer_id = cp.user_id) AS referrals_made,
    cp.plan_status
   FROM customer_profiles cp
     LEFT JOIN customers c ON c.email = (( SELECT p.email
           FROM profiles p
          WHERE p.id = cp.user_id))
     LEFT JOIN subscriptions s ON s.customer_id = c.id AND s.status = 'active'::text;
CREATE OR REPLACE VIEW public.v_api_keys_admin AS
 SELECT id,
    token_prefix,
    name,
    scopes,
    rate_per_minute,
    status,
    last_used_at,
    last_used_ip,
    request_count,
    expires_at,
    created_at,
    created_by,
    customer_reference,
    ( SELECT count(*) AS count
           FROM api_webhooks w
          WHERE w.api_key_id = k.id) AS webhook_count,
        CASE
            WHEN expires_at IS NOT NULL AND expires_at < now() THEN 'expired'::text
            WHEN status = 'active'::text THEN 'active'::text
            ELSE status
        END AS effective_status
   FROM api_keys k
  ORDER BY created_at DESC;
CREATE OR REPLACE VIEW public.chamber_rental_revenue AS
 SELECT route,
    count(*) AS total_chambers,
    sum(capacity_slots) AS total_slots,
    sum(slots_used) AS tellinex_slots,
    sum(slots_rented) AS rented_slots,
    sum(capacity_slots - slots_used - slots_rented) AS available_slots,
    sum(slots_rented::double precision * rental_rate_usd_month) AS monthly_rental_usd,
    sum(slots_rented::double precision * rental_rate_usd_month * 12::double precision) AS annual_rental_usd
   FROM chamber_registry
  WHERE status = 'active'::text
  GROUP BY route;
CREATE OR REPLACE VIEW public.job_financials AS
 SELECT id AS job_id,
    title,
    zone,
    crew,
    priority,
    status,
    created_at,
    ( SELECT count(*) AS count
           FROM otdr_reports
          WHERE otdr_reports.job_id = j.id) AS otdr_count,
    ( SELECT count(*) AS count
           FROM photo_evidence pe
          WHERE pe.job_id::text = j.id) AS photos_count,
    ( SELECT count(*) AS count
           FROM material_logs ml
          WHERE ml.job_id::text = j.id) AS materials_logged,
    ( SELECT count(*) AS count
           FROM certification_results
          WHERE certification_results.job_id = j.id) AS certifications_run,
    ( SELECT count(*) AS count
           FROM certification_results
          WHERE certification_results.job_id = j.id AND certification_results.decision = 'auto_approved'::text) AS auto_approved_count
   FROM fp_jobs j;
CREATE OR REPLACE VIEW public.security_events_unified AS
 SELECT access_audit_log.id::text AS event_id,
    'access_audit'::text AS source,
    access_audit_log.created_at AS event_time,
    COALESCE(access_audit_log.user_email, access_audit_log.user_name, 'unknown'::text) AS actor,
    access_audit_log.action AS event_type,
    COALESCE((access_audit_log.entity_type || ':'::text) || access_audit_log.entity_id, access_audit_log.section) AS target,
    access_audit_log.platform,
    access_audit_log.details AS detail,
    'info'::text AS severity
   FROM access_audit_log
  WHERE access_audit_log.created_at > (now() - '365 days'::interval)
UNION ALL
 SELECT soc2_incidents.id::text AS event_id,
    'incident'::text AS source,
    soc2_incidents.detected_at AS event_time,
    COALESCE(soc2_incidents.assigned_to, 'unassigned'::text) AS actor,
    (soc2_incidents.category || '/'::text) || soc2_incidents.severity AS event_type,
    soc2_incidents.title AS target,
    NULL::text AS platform,
    soc2_incidents.description AS detail,
    soc2_incidents.severity
   FROM soc2_incidents
  WHERE soc2_incidents.detected_at > (now() - '365 days'::interval)
UNION ALL
 SELECT opus_events.id::text AS event_id,
    'opus_event'::text AS source,
    opus_events.created_at AS event_time,
    COALESCE(opus_events.platform, 'opus'::text) AS actor,
    opus_events.event_type,
    COALESCE(opus_events.metadata ->> 'target'::text, 'system'::text) AS target,
    opus_events.platform,
    COALESCE(opus_events.message, ''::text) AS detail,
    COALESCE(opus_events.severity, 'info'::text) AS severity
   FROM opus_events
  WHERE opus_events.created_at > (now() - '365 days'::interval)
UNION ALL
 SELECT stripe_events.id::text AS event_id,
    'stripe_event'::text AS source,
    stripe_events.created_at AS event_time,
    'stripe'::text AS actor,
    stripe_events.event_type,
    stripe_events.stripe_event_id AS target,
    'stripe'::text AS platform,
    ''::text AS detail,
    'info'::text AS severity
   FROM stripe_events
  WHERE stripe_events.created_at > (now() - '365 days'::interval);
CREATE OR REPLACE VIEW public.security_feed AS
 SELECT 'iloq:'::text || ial.id::text AS feed_id,
    'iloq'::text AS source,
    ial.created_at AS event_time,
    COALESCE(ial.asset_ref, ial.lock_id) AS target,
    ial.technician_name AS actor,
    ial.action AS event_type,
        CASE
            WHEN ial.flagged THEN 'high'::text
            WHEN ial.action = 'emergency_open'::text THEN 'critical'::text
            ELSE 'info'::text
        END AS severity,
    ial.flag_reason AS detail,
    ial.latitude AS lat,
    ial.longitude AS lng,
    NULL::uuid AS incident_id
   FROM iloq_access_log ial
UNION ALL
 SELECT 'cctv:'::text || ca.id::text AS feed_id,
    'axis'::text AS source,
    ca.created_at AS event_time,
    c.location_desc AS target,
    NULL::text AS actor,
    ca.alert_type AS event_type,
    ca.severity,
    ca.description AS detail,
    c.lat,
    c.lng,
    NULL::uuid AS incident_id
   FROM cctv_alerts ca
     LEFT JOIN cctv_cameras c ON c.id = ca.camera_id
UNION ALL
 SELECT 'sensor:'::text || csr.id::text AS feed_id,
    'lorawan'::text AS source,
    csr.created_at AS event_time,
    csr.asset_ref AS target,
    NULL::text AS actor,
    COALESCE(csr.alert_type, csr.reading_type) AS event_type,
        CASE
            WHEN csr.is_alert THEN 'high'::text
            ELSE 'info'::text
        END AS severity,
    NULL::text AS detail,
    NULL::numeric AS lat,
    NULL::numeric AS lng,
    NULL::uuid AS incident_id
   FROM chamber_sensor_readings csr
UNION ALL
 SELECT 'incident:'::text || si.id::text AS feed_id,
    'opus'::text AS source,
    si.created_at AS event_time,
    si.asset_ref AS target,
    'Opus 4.7'::text AS actor,
    si.primary_event_type AS event_type,
    si.severity,
    si.opus_summary AS detail,
    si.latitude AS lat,
    si.longitude AS lng,
    si.id AS incident_id
   FROM security_incidents si
  ORDER BY 3 DESC;
CREATE OR REPLACE VIEW public.soc2_dashboard_summary AS
 SELECT ( SELECT count(*) AS count
           FROM soc2_controls) AS total_controls,
    ( SELECT count(*) AS count
           FROM soc2_controls
          WHERE soc2_controls.implementation_status = 'implemented'::text) AS controls_implemented,
    ( SELECT count(*) AS count
           FROM soc2_controls
          WHERE soc2_controls.implementation_status = 'in_progress'::text) AS controls_in_progress,
    ( SELECT count(*) AS count
           FROM soc2_controls
          WHERE soc2_controls.implementation_status = 'planned'::text) AS controls_planned,
    ( SELECT count(*) AS count
           FROM soc2_controls
          WHERE soc2_controls.automated = true) AS controls_automated,
    ( SELECT count(*) AS count
           FROM soc2_policies) AS total_policies,
    ( SELECT count(*) AS count
           FROM soc2_policies
          WHERE soc2_policies.status = 'approved'::text) AS policies_approved,
    ( SELECT count(*) AS count
           FROM soc2_policies
          WHERE soc2_policies.status = 'draft'::text) AS policies_draft,
    ( SELECT count(*) AS count
           FROM soc2_policies
          WHERE soc2_policies.status = 'under_review'::text) AS policies_under_review,
    ( SELECT count(*) AS count
           FROM soc2_vendors) AS total_vendors,
    ( SELECT count(*) AS count
           FROM soc2_vendors
          WHERE soc2_vendors.risk_level = ANY (ARRAY['critical'::text, 'high'::text])) AS vendors_high_risk,
    ( SELECT count(*) AS count
           FROM soc2_vendors
          WHERE soc2_vendors.has_soc2 = true) AS vendors_with_soc2,
    ( SELECT count(*) AS count
           FROM soc2_vendors
          WHERE soc2_vendors.next_review_due < (CURRENT_DATE + '30 days'::interval)) AS vendors_review_due_soon,
    ( SELECT count(*) AS count
           FROM soc2_risks) AS total_risks,
    ( SELECT count(*) AS count
           FROM soc2_risks
          WHERE soc2_risks.status = 'open'::text) AS risks_open,
    ( SELECT count(*) AS count
           FROM soc2_risks
          WHERE soc2_risks.inherent_score >= 15) AS risks_high_severity,
    ( SELECT round(avg(soc2_risks.residual_score), 1) AS round
           FROM soc2_risks) AS avg_residual_risk,
    ( SELECT count(*) AS count
           FROM soc2_incidents
          WHERE soc2_incidents.status = ANY (ARRAY['investigating'::text, 'contained'::text])) AS incidents_active,
    ( SELECT count(*) AS count
           FROM soc2_incidents
          WHERE soc2_incidents.detected_at > (CURRENT_DATE - '90 days'::interval)) AS incidents_last_90d,
    ( SELECT count(DISTINCT soc2_training.employee_email) AS count
           FROM soc2_training
          WHERE soc2_training.completed_at > (CURRENT_DATE - '365 days'::interval)) AS employees_trained_last_year,
    ( SELECT count(*) AS count
           FROM soc2_evidence
          WHERE soc2_evidence.captured_at > (CURRENT_DATE - '90 days'::interval)) AS evidence_last_90d,
    round((( SELECT count(*)::numeric AS count
           FROM soc2_controls
          WHERE soc2_controls.implementation_status = 'implemented'::text)) / NULLIF(( SELECT count(*)::numeric AS count
           FROM soc2_controls), 0::numeric) * 40::numeric + (( SELECT count(*)::numeric AS count
           FROM soc2_policies
          WHERE soc2_policies.status = 'approved'::text)) / NULLIF(( SELECT count(*)::numeric AS count
           FROM soc2_policies), 0::numeric) * 30::numeric + (( SELECT count(*)::numeric AS count
           FROM soc2_vendors
          WHERE soc2_vendors.next_review_due > CURRENT_DATE)) / NULLIF(( SELECT count(*)::numeric AS count
           FROM soc2_vendors), 0::numeric) * 15::numeric +
        CASE
            WHEN (( SELECT count(*) AS count
               FROM soc2_evidence
              WHERE soc2_evidence.captured_at > (CURRENT_DATE - '30 days'::interval))) >= 10 THEN 15
            ELSE 0
        END::numeric, 1) AS audit_readiness_pct;
CREATE OR REPLACE VIEW public.v_audit_log_recent AS
 SELECT id,
    occurred_at,
    table_name,
    operation,
    row_id,
    actor_email,
    actor_role,
    client_ip,
    changed_fields,
        CASE operation
            WHEN 'INSERT'::text THEN new_row
            WHEN 'DELETE'::text THEN old_row
            WHEN 'UPDATE'::text THEN ( SELECT jsonb_object_agg(k.k, jsonb_build_object('from', al.old_row -> k.k, 'to', al.new_row -> k.k)) AS jsonb_object_agg
               FROM unnest(al.changed_fields) k(k))
            ELSE NULL::jsonb
        END AS diff
   FROM audit_log al
  WHERE occurred_at > (now() - '90 days'::interval)
  ORDER BY occurred_at DESC;
CREATE OR REPLACE VIEW public.v_customer_journey AS
 SELECT 'registrations'::text AS stage,
    count(*) AS total,
    count(*) FILTER (WHERE registrations.created_at > (now() - '7 days'::interval)) AS last_7d
   FROM registrations
UNION ALL
 SELECT 'quotes'::text AS stage,
    count(*) AS total,
    count(*) FILTER (WHERE quote_requests.created_at > (now() - '7 days'::interval)) AS last_7d
   FROM quote_requests
UNION ALL
 SELECT 'dispatched'::text AS stage,
    count(*) AS total,
    count(*) FILTER (WHERE dispatch_queue.created_at > (now() - '7 days'::interval)) AS last_7d
   FROM dispatch_queue;
CREATE OR REPLACE VIEW public.v_tenant_directory AS
 SELECT t.id,
    t.name,
    t.slug,
    t.country,
    t.region,
    t.status,
    t.plan,
    t.tier,
    t.parent_tenant_id,
    parent.name AS parent_name,
    t.created_at,
    ( SELECT count(*) AS count
           FROM profiles
          WHERE profiles.tenant_id = t.id) AS user_count,
    ( SELECT count(*) AS count
           FROM network_assets
          WHERE network_assets.tenant_id = t.id) AS asset_count,
    ( SELECT count(*) AS count
           FROM work_orders
          WHERE work_orders.tenant_id = t.id) AS work_order_count,
    t.max_users,
    t.max_assets
   FROM tenants t
     LEFT JOIN tenants parent ON t.parent_tenant_id = parent.id
  ORDER BY t.created_at;
CREATE OR REPLACE VIEW public.v_pending_acceptances AS
 SELECT id AS work_order_id,
    title AS work_order_title,
    status AS wo_status,
    assigned_technician,
    created_at AS wo_created_at,
    (EXISTS ( SELECT 1
           FROM digital_acceptances
          WHERE digital_acceptances.work_order_id = wo.id AND digital_acceptances.status = 'submitted'::text)) AS has_tech_acceptance,
    (EXISTS ( SELECT 1
           FROM customer_signoffs
          WHERE customer_signoffs.work_order_id = wo.id AND customer_signoffs.status = 'submitted'::text)) AS has_customer_signoff
   FROM work_orders wo
  WHERE (status = ANY (ARRAY['completed'::text, 'pending_acceptance'::text])) AND NOT (EXISTS ( SELECT 1
           FROM digital_acceptances da
          WHERE da.work_order_id = wo.id AND da.status = 'submitted'::text))
  ORDER BY created_at DESC;
CREATE OR REPLACE VIEW public.v_dispatch_pipeline AS
 SELECT task_type,
    count(*) AS total,
    count(*) FILTER (WHERE status = 'pending'::text) AS pending,
    count(*) FILTER (WHERE status = 'completed'::text) AS completed,
    round(count(*) FILTER (WHERE status = 'completed'::text)::numeric / NULLIF(count(*), 0)::numeric * 100::numeric, 1) AS completion_rate
   FROM dispatch_queue
  GROUP BY task_type
  ORDER BY (count(*) FILTER (WHERE status = 'pending'::text)) DESC;
CREATE OR REPLACE VIEW public.v_inventory_count_sessions AS
 SELECT count_session_id,
    min(scanned_at) AS started_at,
    max(scanned_at) AS last_scan_at,
    count(*) AS items_scanned,
    count(*) FILTER (WHERE variance <> 0) AS items_with_variance,
    sum(variance) AS total_variance,
    array_agg(DISTINCT location) AS locations,
    array_agg(DISTINCT technician_id) AS technicians
   FROM inventory_cycle_counts
  GROUP BY count_session_id
  ORDER BY (max(scanned_at)) DESC;
CREATE OR REPLACE VIEW public.v_etl_health_summary AS
 SELECT source_system,
    count(*) FILTER (WHERE created_at > (now() - '24:00:00'::interval)) AS imports_24h,
    count(*) FILTER (WHERE status = 'succeeded'::text AND created_at > (now() - '24:00:00'::interval)) AS succeeded_24h,
    count(*) FILTER (WHERE status = 'failed'::text AND created_at > (now() - '24:00:00'::interval)) AS failed_24h,
    count(*) FILTER (WHERE status = 'pending'::text AND created_at < (now() - '00:15:00'::interval)) AS stuck_pending,
    max(created_at) AS last_import_at,
        CASE
            WHEN count(*) FILTER (WHERE created_at > (now() - '24:00:00'::interval)) = 0 THEN 'idle'::text
            WHEN count(*) FILTER (WHERE status = 'failed'::text AND created_at > (now() - '24:00:00'::interval)) > count(*) FILTER (WHERE status = 'succeeded'::text AND created_at > (now() - '24:00:00'::interval)) THEN 'degraded'::text
            ELSE 'healthy'::text
        END AS health_status
   FROM etl_imports
  GROUP BY source_system
  ORDER BY (max(created_at)) DESC NULLS LAST;
CREATE OR REPLACE VIEW public.v_recent_etl_imports AS
 SELECT id,
    source_system,
    source_table,
    external_id,
    status,
    records_processed,
    records_failed,
    error_message,
    retries,
    created_at,
    processing_completed_at,
        CASE
            WHEN processing_completed_at IS NOT NULL AND processing_started_at IS NOT NULL THEN EXTRACT(epoch FROM processing_completed_at - processing_started_at)
            ELSE NULL::numeric
        END AS duration_seconds
   FROM etl_imports
  WHERE created_at > (now() - '7 days'::interval)
  ORDER BY created_at DESC;
CREATE OR REPLACE VIEW public.v_edge_function_health AS
 SELECT 'api-webhook-dispatcher'::text AS function_name,
    count(*) FILTER (WHERE api_webhook_deliveries.created_at > (now() - '24:00:00'::interval)) AS invocations_24h,
    count(*) FILTER (WHERE api_webhook_deliveries.created_at > (now() - '24:00:00'::interval) AND api_webhook_deliveries.status = 'delivered'::text) AS success_24h,
    count(*) FILTER (WHERE api_webhook_deliveries.created_at > (now() - '24:00:00'::interval) AND api_webhook_deliveries.status = 'permanent_failure'::text) AS fail_24h,
    max(api_webhook_deliveries.delivered_at) FILTER (WHERE api_webhook_deliveries.status = 'delivered'::text) AS last_success_at
   FROM api_webhook_deliveries
UNION ALL
 SELECT 'asset-health-rescore'::text AS function_name,
    count(*) AS invocations_24h,
    NULL::bigint AS success_24h,
    NULL::bigint AS fail_24h,
    max(asset_health_rescore_queue.enqueued_at) AS last_success_at
   FROM asset_health_rescore_queue
  WHERE asset_health_rescore_queue.enqueued_at > (now() - '24:00:00'::interval);
CREATE OR REPLACE VIEW public.otel_service_health AS
 SELECT root_service,
    count(*) FILTER (WHERE started_at > (now() - '01:00:00'::interval)) AS traces_1h,
    count(*) FILTER (WHERE status = 'error'::text AND started_at > (now() - '01:00:00'::interval)) AS errors_1h,
    round(avg(duration_ms) FILTER (WHERE status = 'ok'::text AND started_at > (now() - '01:00:00'::interval)))::integer AS p_avg_ms_1h,
    percentile_disc(0.95::double precision) WITHIN GROUP (ORDER BY duration_ms) FILTER (WHERE started_at > (now() - '01:00:00'::interval)) AS p95_ms_1h,
    max(started_at) AS last_trace_at
   FROM otel_traces
  GROUP BY root_service;
CREATE OR REPLACE VIEW public.synthetic_test_health AS
 SELECT scenario,
    count(*) FILTER (WHERE started_at > (now() - '24:00:00'::interval)) AS runs_24h,
    count(*) FILTER (WHERE status = 'passed'::text AND started_at > (now() - '24:00:00'::interval)) AS passed_24h,
    count(*) FILTER (WHERE status = 'failed'::text AND started_at > (now() - '24:00:00'::interval)) AS failed_24h,
    round(100.0 * count(*) FILTER (WHERE status = 'passed'::text AND started_at > (now() - '24:00:00'::interval))::numeric / NULLIF(count(*) FILTER (WHERE started_at > (now() - '24:00:00'::interval)), 0)::numeric, 2) AS pass_rate_24h_pct,
    round(avg(duration_ms) FILTER (WHERE status = 'passed'::text AND started_at > (now() - '24:00:00'::interval)))::integer AS avg_duration_ms,
    max(started_at) AS last_run_at,
    max(started_at) FILTER (WHERE status = 'passed'::text) AS last_passing_run_at
   FROM synthetic_test_runs
  GROUP BY scenario;
CREATE OR REPLACE VIEW public.v_active_health_alerts AS
 SELECT id,
    alert_type,
    severity,
    component,
    message,
    details,
    detected_at,
    EXTRACT(epoch FROM now() - detected_at) / 60.0 AS age_minutes
   FROM system_health_alerts
  WHERE resolved_at IS NULL
  ORDER BY (
        CASE severity
            WHEN 'critical'::text THEN 1
            WHEN 'error'::text THEN 2
            WHEN 'warning'::text THEN 3
            ELSE 4
        END), detected_at DESC;
CREATE OR REPLACE VIEW public.v_active_ar_calibrations AS
 SELECT job_site_id,
    job_id,
    count(*) AS calibration_count,
    max(created_at) AS latest_calibration_at,
    ( SELECT c2.id
           FROM ar_calibration_anchors c2
          WHERE c2.job_site_id = c.job_site_id AND c2.invalidated_at IS NULL AND (c2.expires_at IS NULL OR c2.expires_at > now())
          ORDER BY c2.created_at DESC
         LIMIT 1) AS active_calibration_id,
    min(rtk_accuracy_avg_m) AS best_avg_accuracy_m,
    max(rtk_accuracy_avg_m) AS worst_avg_accuracy_m
   FROM ar_calibration_anchors c
  WHERE invalidated_at IS NULL
  GROUP BY job_site_id, job_id;
CREATE OR REPLACE VIEW public.v_predictive_model_summary AS
 SELECT count(*) AS total_feedback,
    sum(
        CASE
            WHEN outcome = ANY (ARRAY['confirmed_critical'::text, 'confirmed_warning'::text, 'completed_proactive'::text]) THEN 1
            ELSE 0
        END) AS true_positives,
    sum(
        CASE
            WHEN outcome = ANY (ARRAY['false_positive'::text, 'superseded'::text]) THEN 1
            ELSE 0
        END) AS false_positives,
        CASE
            WHEN (sum(
            CASE
                WHEN outcome = ANY (ARRAY['confirmed_critical'::text, 'confirmed_warning'::text, 'completed_proactive'::text]) THEN 1
                ELSE 0
            END) + sum(
            CASE
                WHEN outcome = ANY (ARRAY['false_positive'::text, 'superseded'::text]) THEN 1
                ELSE 0
            END)) = 0 THEN NULL::numeric
            ELSE round(sum(
            CASE
                WHEN outcome = ANY (ARRAY['confirmed_critical'::text, 'confirmed_warning'::text, 'completed_proactive'::text]) THEN 1
                ELSE 0
            END)::numeric / NULLIF(sum(
            CASE
                WHEN outcome = ANY (ARRAY['confirmed_critical'::text, 'confirmed_warning'::text, 'completed_proactive'::text]) THEN 1
                ELSE 0
            END) + sum(
            CASE
                WHEN outcome = ANY (ARRAY['false_positive'::text, 'superseded'::text]) THEN 1
                ELSE 0
            END), 0)::numeric * 100::numeric, 1)
        END AS overall_precision_pct,
    round(avg(triggering_score), 3) AS avg_triggering_score,
    count(DISTINCT triggering_asset_id) AS distinct_assets_evaluated,
    min(marked_at) AS earliest_feedback_at,
    max(marked_at) AS latest_feedback_at
   FROM predictive_feedback;
CREATE OR REPLACE VIEW public.v_predictive_model_precision AS
 WITH f AS (
         SELECT pf.outcome,
            na.asset_type,
            pf.triggering_score,
            pf.draft_to_feedback_minutes,
                CASE
                    WHEN pf.outcome = ANY (ARRAY['confirmed_critical'::text, 'confirmed_warning'::text, 'completed_proactive'::text]) THEN 1
                    ELSE 0
                END AS is_true_positive,
                CASE
                    WHEN pf.outcome = ANY (ARRAY['false_positive'::text, 'superseded'::text]) THEN 1
                    ELSE 0
                END AS is_false_positive,
                CASE
                    WHEN pf.outcome = 'inaccessible'::text THEN 1
                    ELSE 0
                END AS is_inaccessible
           FROM predictive_feedback pf
             LEFT JOIN network_assets na ON na.id = pf.triggering_asset_id
        )
 SELECT COALESCE(asset_type, 'unknown'::text) AS asset_type,
    count(*) AS total_feedback,
    sum(is_true_positive) AS true_positives,
    sum(is_false_positive) AS false_positives,
    sum(is_inaccessible) AS inaccessible,
        CASE
            WHEN (sum(is_true_positive) + sum(is_false_positive)) = 0 THEN NULL::numeric
            ELSE round(sum(is_true_positive)::numeric / NULLIF(sum(is_true_positive) + sum(is_false_positive), 0)::numeric * 100::numeric, 1)
        END AS precision_pct,
    round(avg(triggering_score), 3) AS avg_triggering_score,
    round(avg(draft_to_feedback_minutes), 0) AS avg_minutes_to_feedback
   FROM f
  GROUP BY asset_type
  ORDER BY (count(*)) DESC, (COALESCE(asset_type, 'unknown'::text));
CREATE OR REPLACE VIEW public.v_predictive_work_orders AS
 SELECT wo.id,
    wo.reference,
    wo.title,
    wo.priority,
    wo.status,
    wo.work_type,
    wo.required_role,
    wo.assigned_technician,
    wo.created_at,
    wo.updated_at,
    wo.dispatched_at,
    wo.completed_at,
    wo.triggering_asset_id,
    wo.triggering_score,
    wo.triggering_components,
    na.asset_ref,
    na.asset_type,
    na.address AS asset_address,
    na.latitude AS asset_lat,
    na.longitude AS asset_lng,
    ahs.computed_at AS score_computed_at,
    ahs.trend AS score_trend,
    ahs.recommended_action,
        CASE
            WHEN wo.triggering_score < 0.10 THEN 'critical'::text
            WHEN wo.triggering_score < 0.30 THEN 'warning'::text
            ELSE 'watch'::text
        END AS flag_level
   FROM work_orders wo
     LEFT JOIN network_assets na ON na.id = wo.triggering_asset_id
     LEFT JOIN asset_health_scores ahs ON ahs.id = wo.triggering_health_score_id
  WHERE wo.source_kind = 'predictive_maintenance'::text
  ORDER BY (
        CASE wo.priority
            WHEN 'critical'::text THEN 1
            WHEN 'high'::text THEN 2
            WHEN 'normal'::text THEN 3
            WHEN 'low'::text THEN 4
            ELSE NULL::integer
        END), wo.triggering_score, wo.created_at DESC;
CREATE OR REPLACE VIEW public.v_asset_health_daily_by_type AS
 SELECT date_trunc('day'::text, ahs.computed_at)::date AS day,
    COALESCE(na.asset_type, 'unknown'::text) AS asset_type,
    count(*) AS samples,
    count(DISTINCT ahs.asset_id) AS distinct_assets,
    round(avg(ahs.score), 3) AS avg_score,
    round(min(ahs.score), 3) AS min_score,
    round(percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (ahs.score::double precision))::numeric, 3) AS median_score,
    round(percentile_cont(0.1::double precision) WITHIN GROUP (ORDER BY (ahs.score::double precision))::numeric, 3) AS p10_score,
    sum(
        CASE
            WHEN ahs.score < 0.10 THEN 1
            ELSE 0
        END) AS critical_count,
    sum(
        CASE
            WHEN ahs.score >= 0.10 AND ahs.score < 0.30 THEN 1
            ELSE 0
        END) AS warning_count,
    sum(
        CASE
            WHEN ahs.score >= 0.30 AND ahs.score < 0.60 THEN 1
            ELSE 0
        END) AS watch_count
   FROM asset_health_scores ahs
     LEFT JOIN network_assets na ON na.id = ahs.asset_id
  GROUP BY (date_trunc('day'::text, ahs.computed_at)::date), (COALESCE(na.asset_type, 'unknown'::text))
  ORDER BY (date_trunc('day'::text, ahs.computed_at)::date) DESC, (COALESCE(na.asset_type, 'unknown'::text));
CREATE OR REPLACE VIEW public.v_assets_needing_attention AS
 SELECT na.id AS asset_id,
    na.asset_ref,
    na.asset_type,
    na.address,
    na.health_score AS cached_score_pct,
    ahs.score AS latest_score,
    ahs.trend,
    ahs.recommended_action,
    ahs.components,
    ahs.computed_at AS last_computed_at,
        CASE
            WHEN ahs.score < 0.10 THEN 'critical'::text
            WHEN ahs.score < 0.30 THEN 'warning'::text
            WHEN ahs.score < 0.60 THEN 'watch'::text
            ELSE 'ok'::text
        END AS flag_level
   FROM network_assets na
     LEFT JOIN LATERAL ( SELECT asset_health_scores.score,
            asset_health_scores.trend,
            asset_health_scores.recommended_action,
            asset_health_scores.components,
            asset_health_scores.computed_at
           FROM asset_health_scores
          WHERE asset_health_scores.asset_id = na.id
          ORDER BY asset_health_scores.computed_at DESC
         LIMIT 1) ahs ON true
  WHERE ahs.score IS NOT NULL AND ahs.score < 0.60
  ORDER BY ahs.score, ahs.computed_at DESC;
CREATE OR REPLACE VIEW public.v_upcoming_maintenance_windows AS
 SELECT mw.id,
    mw.work_order_id,
    mw.asset_id,
    mw.scheduled_start,
    mw.scheduled_end,
    mw.status,
    mw.source,
    mw.estimated_duration_minutes,
    mw.assigned_technician AS window_assigned_technician,
    na.asset_ref,
    na.asset_type,
    na.address AS asset_address,
    na.latitude AS asset_lat,
    na.longitude AS asset_lng,
    wo.reference AS wo_reference,
    wo.title AS wo_title,
    wo.priority AS wo_priority,
    wo.required_role,
    wo.assigned_technician AS wo_assigned_technician,
    wo.triggering_score,
        CASE
            WHEN mw.scheduled_start < now() AND mw.status = 'tentative'::text THEN true
            ELSE false
        END AS is_overdue
   FROM maintenance_windows mw
     LEFT JOIN network_assets na ON na.id = mw.asset_id
     LEFT JOIN work_orders wo ON wo.id = mw.work_order_id
  WHERE mw.status = ANY (ARRAY['tentative'::text, 'confirmed'::text, 'in_progress'::text])
  ORDER BY mw.scheduled_start;
CREATE OR REPLACE VIEW public.v_form_defaults_health AS
 SELECT form_name,
    count(*) AS default_count,
    count(DISTINCT technician_id) FILTER (WHERE technician_id IS NOT NULL) AS unique_techs,
    count(DISTINCT asset_type) FILTER (WHERE asset_type IS NOT NULL) AS unique_asset_types,
    avg(confidence) AS avg_confidence,
    max(use_count) AS max_use_count,
    max(last_used_at) AS most_recent_use
   FROM form_field_defaults
  GROUP BY form_name
  ORDER BY (sum(use_count)) DESC;
CREATE OR REPLACE VIEW public.router_health_current AS
 SELECT user_id,
    router_id,
    avg(health_score)::numeric(5,2) AS avg_score_24h,
    max(temperature_c) AS peak_temp_24h,
    sum(reboot_count_24h) AS reboots_24h,
    max(predicted_failure_within_days) AS predicted_failure_days,
    max(reported_at) AS last_check,
        CASE
            WHEN max(predicted_failure_within_days) IS NOT NULL THEN 'replacement_recommended'::text
            WHEN avg(health_score) < 60::numeric THEN 'degraded'::text
            WHEN avg(health_score) < 85::numeric THEN 'fair'::text
            ELSE 'healthy'::text
        END AS status
   FROM router_health_readings r
  WHERE reported_at > (now() - '24:00:00'::interval)
  GROUP BY user_id, router_id;
CREATE OR REPLACE VIEW public.network_link_with_cables AS
 SELECT ntl.id,
    ntl.from_asset_id,
    ntl.to_asset_id,
    ntl.link_type,
    ntl.length_m,
    ntl.bearing_deg,
    ntl.status,
    ntl.installed_date,
    ntl.last_tested,
    ntl.otdr_trace_url,
    ntl.capacity_used_pct,
    ntl.waypoints_3d,
    ntl.notes,
    ntl.created_at,
    ntl.updated_at,
    ntl.is_container,
    ntl.max_cables,
    ntl.container_type,
    count(cp.id) AS cable_count,
    ntl.max_cables - count(cp.id) AS free_slots,
    count(cp.id) FILTER (WHERE cp.status = 'active'::text) AS active_cables,
    count(cp.id) FILTER (WHERE cp.status = 'faulted'::text) AS faulted_cables,
    count(cp.id) FILTER (WHERE cp.status = 'reserved'::text) AS reserved_cables,
    array_agg(cp.cable_ref ORDER BY cp.sub_tube_position) FILTER (WHERE cp.id IS NOT NULL) AS cable_refs
   FROM network_topology_links ntl
     LEFT JOIN cable_pulls cp ON cp.through_link_id = ntl.id
  GROUP BY ntl.id;
CREATE OR REPLACE VIEW public.network_customer_impact AS
 SELECT id AS asset_id,
    asset_type,
    asset_ref,
    status,
    latitude,
    longitude,
    address,
    ( SELECT count(*) AS count
           FROM customer_profiles cp
          WHERE cp.address ~~* (('%'::text || COALESCE(na.address, ''::text)) || '%'::text) AND cp.plan_status = 'active'::text) AS customers_nearby,
    ( SELECT count(*) AS count
           FROM network_incidents
          WHERE network_incidents.status = ANY (ARRAY['active'::text, 'investigating'::text])) AS active_incidents_total,
    updated_at AS last_asset_update
   FROM network_assets na;
CREATE OR REPLACE VIEW public.v_network_health AS
 SELECT asset_type,
    count(*) AS total,
    count(*) FILTER (WHERE status = 'active'::text) AS active,
    count(*) FILTER (WHERE status = 'installed'::text) AS installed,
    count(*) FILTER (WHERE status = 'planned'::text) AS planned,
    count(*) FILTER (WHERE status = 'faulty'::text) AS faulty,
    count(*) FILTER (WHERE inspection_status = 'certified'::text) AS certified,
    sum(fibre_count) AS total_fibres,
    round(count(*) FILTER (WHERE status = 'active'::text)::numeric / NULLIF(count(*), 0)::numeric * 100::numeric, 1) AS active_pct
   FROM network_assets
  GROUP BY asset_type
  ORDER BY (count(*)) DESC;
CREATE OR REPLACE VIEW public.network_telemetry_latest AS
 SELECT DISTINCT ON (asset_id) asset_id,
    asset_ref,
    polled_at,
    rx_power_dbm,
    tx_power_dbm,
    temperature_c,
    uptime_seconds,
    active_clients,
    status,
    poll_source,
    EXTRACT(epoch FROM now() - polled_at)::integer AS seconds_since_poll
   FROM network_telemetry nt
  ORDER BY asset_id, polled_at DESC;
CREATE OR REPLACE VIEW public.field_ops_live AS
 SELECT id AS job_id,
    title,
    zone,
    crew,
    status,
    priority,
    nwa,
    route_m,
    created_at,
    updated_at,
    ( SELECT count(*)::integer AS count
           FROM fp_splices fs
          WHERE fs.chamber_id IS NOT NULL AND (EXISTS ( SELECT 1
                   FROM chambers ch
                  WHERE ch.id::text = fs.chamber_id AND ch.job_id::text = fj.id))) AS splices_done,
    ( SELECT count(*)::integer AS count
           FROM photo_evidence pe
          WHERE pe.job_id::text = fj.id) AS photos_captured,
    ( SELECT count(*)::integer AS count
           FROM otdr_reports ot
          WHERE ot.job_id = fj.id) AS otdr_runs,
    ( SELECT count(*)::integer AS count
           FROM otdr_reports ot
          WHERE ot.job_id = fj.id AND ot.pass = true) AS otdr_passed,
    ( SELECT count(*)::integer AS count
           FROM otdr_reports ot
          WHERE ot.job_id = fj.id AND ot.opus_validated = true) AS otdr_opus_validated
   FROM fp_jobs fj;
CREATE OR REPLACE VIEW public.v_fleet_utilisation AS
 SELECT vehicle_id,
    (make || ' '::text) || model AS vehicle_desc,
    status,
    registration,
    fuel_level_pct,
    ( SELECT count(*) AS count
           FROM fleet_preflight_checks p
          WHERE p.vehicle_id = v.vehicle_id AND p.check_date = CURRENT_DATE) AS preflights_today,
    ( SELECT count(*) AS count
           FROM vehicle_inventory i
          WHERE i.vehicle_id = v.vehicle_id AND i.quantity < i.min_threshold) AS low_stock_items,
    ( SELECT count(*) AS count
           FROM dispatch_queue d
          WHERE d.assigned_vehicle = v.vehicle_id AND (d.status = ANY (ARRAY['assigned'::text, 'in_progress'::text]))) AS active_tasks
   FROM fleet_vehicles v
  ORDER BY vehicle_id;
CREATE OR REPLACE VIEW public.v_i18n_coverage AS
 SELECT code AS locale,
    english_name,
    ( SELECT count(*) AS count
           FROM i18n_translations
          WHERE i18n_translations.locale = 'en'::text) AS base_keys,
    ( SELECT count(*) AS count
           FROM i18n_translations
          WHERE i18n_translations.locale = l.code) AS translated_keys,
    round(100.0 * (( SELECT count(*) AS count
           FROM i18n_translations
          WHERE i18n_translations.locale = l.code))::numeric / NULLIF(( SELECT count(*) AS count
           FROM i18n_translations
          WHERE i18n_translations.locale = 'en'::text), 0)::numeric, 1) AS coverage_pct
   FROM i18n_locales l
  WHERE is_active
  ORDER BY (round(100.0 * (( SELECT count(*) AS count
           FROM i18n_translations
          WHERE i18n_translations.locale = l.code))::numeric / NULLIF(( SELECT count(*) AS count
           FROM i18n_translations
          WHERE i18n_translations.locale = 'en'::text), 0)::numeric, 1)) DESC NULLS LAST;
CREATE OR REPLACE VIEW public.v_tenant_hierarchy AS
 WITH RECURSIVE hierarchy AS (
         SELECT tenants.id,
            tenants.name,
            tenants.slug,
            tenants.tier,
            tenants.parent_tenant_id,
            tenants.country,
            tenants.region,
            tenants.status,
            0 AS depth,
            tenants.name AS path
           FROM tenants
          WHERE tenants.parent_tenant_id IS NULL
        UNION ALL
         SELECT t.id,
            t.name,
            t.slug,
            t.tier,
            t.parent_tenant_id,
            t.country,
            t.region,
            t.status,
            h.depth + 1,
            (h.path || ' → '::text) || t.name AS text
           FROM tenants t
             JOIN hierarchy h ON t.parent_tenant_id = h.id
        )
 SELECT repeat('  '::text, depth) || name AS display_name,
    id,
    name,
    slug,
    tier,
    country,
    region,
    status,
    parent_tenant_id,
    depth,
    path
   FROM hierarchy
  ORDER BY path;
CREATE OR REPLACE VIEW public.gpr_surveys_by_job AS
 SELECT s.job_id,
    count(DISTINCT s.id) AS survey_count,
    sum(s.detection_count) AS total_detections,
    max(s.max_depth_m) AS deepest_finding_m,
    max(s.survey_date) AS latest_survey_date,
    array_agg(DISTINCT s.source_device) AS devices_used,
    array_agg(DISTINCT d.object_type) FILTER (WHERE d.object_type IS NOT NULL) AS object_types_found
   FROM gpr_surveys s
     LEFT JOIN gpr_detections d ON d.survey_id = s.id
  WHERE s.parsing_status = 'parsed'::text
  GROUP BY s.job_id;
CREATE OR REPLACE VIEW public.gpr_surveys_map AS
 SELECT s.id,
    s.survey_name,
    s.job_id,
    s.source_device,
    s.source_format,
    s.survey_date,
    s.center_lat,
    s.center_lng,
    s.detection_count,
    s.max_depth_m,
    s.parsing_status,
    s.created_at,
    COALESCE(max(
        CASE
            WHEN d.object_type = 'gas'::text THEN 5
            WHEN d.object_type = ANY (ARRAY['electric'::text, 'utility_cable'::text]) THEN 4
            WHEN d.object_type = ANY (ARRAY['water'::text, 'sewer'::text, 'telecom'::text, 'fibre'::text]) THEN 3
            WHEN d.object_type = ANY (ARRAY['utility_pipe'::text, 'conduit'::text]) THEN 2
            WHEN d.object_type = 'rebar'::text THEN 1
            ELSE 2
        END), 0) AS max_hazard_level,
    array_agg(DISTINCT d.object_type) FILTER (WHERE d.object_type IS NOT NULL) AS object_types
   FROM gpr_surveys s
     LEFT JOIN gpr_detections d ON d.survey_id = s.id
  WHERE s.center_lat IS NOT NULL AND s.center_lng IS NOT NULL AND s.parsing_status = 'parsed'::text
  GROUP BY s.id, s.survey_name, s.job_id, s.source_device, s.source_format, s.survey_date, s.center_lat, s.center_lng, s.detection_count, s.max_depth_m, s.parsing_status, s.created_at;
CREATE OR REPLACE VIEW public.gpr_detections_enriched AS
 SELECT d.id AS detection_id,
    d.survey_id,
    s.job_id,
    s.survey_name,
    s.source_device,
    s.survey_date,
    d.tag_label,
    d.object_type,
    d.confidence,
    d.depth_m,
    d.diameter_mm,
    d.bearing_deg,
    d.position_along_m,
    d.position_across_m,
    COALESCE(d.lat, s.center_lat) AS effective_lat,
    COALESCE(d.lng, s.center_lng) AS effective_lng,
    d.raw_metadata,
    d.created_at
   FROM gpr_detections d
     JOIN gpr_surveys s ON s.id = d.survey_id
  WHERE s.parsing_status = 'parsed'::text;
CREATE OR REPLACE VIEW public.splice_tray_summary AS
 SELECT st.id AS tray_id,
    st.closure_asset_id,
    na.asset_ref AS closure_ref,
    na.geometry_type AS closure_type,
    st.tray_number,
    st.tray_type,
    st.max_splices,
    count(fs.id) AS splices_made,
    count(fs.id) FILTER (WHERE fs.status = 'active'::text) AS active_splices,
    count(fs.id) FILTER (WHERE fs.status = 'faulted'::text) AS faulted_splices,
    avg(fs.loss_db) FILTER (WHERE fs.loss_db IS NOT NULL) AS avg_loss_db,
    max(fs.loss_db) FILTER (WHERE fs.loss_db IS NOT NULL) AS worst_loss_db
   FROM splice_trays st
     JOIN network_assets na ON na.id = st.closure_asset_id
     LEFT JOIN fibre_splices fs ON fs.tray_id = st.id
  GROUP BY st.id, na.asset_ref, na.geometry_type, st.tray_number, st.tray_type, st.max_splices;
CREATE OR REPLACE VIEW public.v_api_webhooks_admin AS
 SELECT w.id,
    w.api_key_id,
    k.name AS api_key_name,
    k.token_prefix,
    w.url,
    w.event_filter,
    w.status,
    w.last_delivery_at,
    w.last_delivery_status,
    w.consecutive_failures,
    w.created_at,
    ( SELECT count(*) AS count
           FROM api_webhook_deliveries d
          WHERE d.webhook_id = w.id AND d.status = 'pending'::text) AS pending_deliveries,
    ( SELECT count(*) AS count
           FROM api_webhook_deliveries d
          WHERE d.webhook_id = w.id AND d.status = 'permanently_failed'::text) AS failed_deliveries
   FROM api_webhooks w
     LEFT JOIN api_keys k ON k.id = w.api_key_id
  ORDER BY w.created_at DESC;
CREATE OR REPLACE VIEW public.v_procurement_dashboard AS
 SELECT status,
    count(*) AS order_count,
    to_char(sum(estimated_total), '$9,999,999,999'::text) AS estimated_total,
    to_char(sum(COALESCE(actual_total, quoted_total, estimated_total)), '$9,999,999,999'::text) AS best_estimate_total,
    array_agg(order_ref ORDER BY procurement_orders.estimated_total DESC) AS order_refs
   FROM procurement_orders
  GROUP BY status
  ORDER BY (
        CASE status
            WHEN 'planned'::text THEN 1
            WHEN 'quoting'::text THEN 2
            WHEN 'approved'::text THEN 3
            WHEN 'ordered'::text THEN 4
            WHEN 'shipped'::text THEN 5
            WHEN 'partial'::text THEN 6
            WHEN 'received'::text THEN 7
            WHEN 'in_service'::text THEN 8
            WHEN 'rejected'::text THEN 9
            WHEN 'cancelled'::text THEN 10
            ELSE NULL::integer
        END);
CREATE OR REPLACE VIEW public.v_procurement_master AS
 SELECT order_ref,
    vendor_name,
    category,
    status AS po_status,
    estimated_total,
    quoted_total,
    actual_total,
    currency,
    capex_category,
    business_plan_section,
    vendor_contact_email,
    vendor_contact_url,
    ( SELECT c.status
           FROM procurement_communications c
          WHERE c.order_id = o.id
          ORDER BY c.created_at DESC
         LIMIT 1) AS last_comm_status,
    ( SELECT c.direction
           FROM procurement_communications c
          WHERE c.order_id = o.id
          ORDER BY c.created_at DESC
         LIMIT 1) AS last_comm_direction,
    ( SELECT c.subject
           FROM procurement_communications c
          WHERE c.order_id = o.id
          ORDER BY c.created_at DESC
         LIMIT 1) AS last_comm_subject,
    ( SELECT c.created_at
           FROM procurement_communications c
          WHERE c.order_id = o.id
          ORDER BY c.created_at DESC
         LIMIT 1) AS last_comm_at,
    ( SELECT count(*) AS count
           FROM procurement_communications c
          WHERE c.order_id = o.id) AS comm_count,
    ( SELECT count(*) AS count
           FROM procurement_communications c
          WHERE c.order_id = o.id AND c.status = 'drafted'::text) AS drafted_count,
    ( SELECT count(*) AS count
           FROM procurement_communications c
          WHERE c.order_id = o.id AND c.response_required AND c.responded_at IS NULL) AS awaiting_response,
    ( SELECT count(*) AS count
           FROM procurement_order_items i
          WHERE i.order_id = o.id) AS line_count,
    notes,
    created_at,
    updated_at
   FROM procurement_orders o
  ORDER BY (
        CASE status
            WHEN 'planned'::text THEN 1
            WHEN 'quoting'::text THEN 2
            WHEN 'approved'::text THEN 3
            WHEN 'ordered'::text THEN 4
            WHEN 'shipped'::text THEN 5
            WHEN 'partial'::text THEN 6
            WHEN 'received'::text THEN 7
            WHEN 'in_service'::text THEN 8
            ELSE 9
        END), estimated_total DESC NULLS LAST;
CREATE OR REPLACE VIEW public.v_procurement_summary AS
 SELECT o.id,
    o.order_ref,
    o.vendor_name,
    o.category,
    o.status,
    o.purpose,
    o.estimated_total,
    o.quoted_total,
    o.actual_total,
    o.currency,
    o.needed_by,
    o.ordered_at,
    o.shipped_at,
    o.received_at,
    o.business_plan_section,
    count(i.id) AS line_count,
    sum(i.quantity) AS total_qty,
    sum(i.received_quantity) AS received_qty,
    o.created_at
   FROM procurement_orders o
     LEFT JOIN procurement_order_items i ON i.order_id = o.id
  GROUP BY o.id
  ORDER BY (
        CASE o.status
            WHEN 'planned'::text THEN 1
            WHEN 'quoting'::text THEN 2
            WHEN 'approved'::text THEN 3
            WHEN 'ordered'::text THEN 4
            WHEN 'shipped'::text THEN 5
            WHEN 'partial'::text THEN 6
            WHEN 'received'::text THEN 7
            WHEN 'in_service'::text THEN 8
            ELSE 9
        END), o.needed_by;
CREATE OR REPLACE VIEW public.v_procurement_communications AS
 SELECT pc.id,
    po.order_ref,
    pc.order_id,
    pc.direction,
    pc.channel,
    pc.subject,
    pc.recipient_email,
    pc.recipient_name,
    pc.sender_email,
    pc.body,
    pc.attachment_urls,
    pc.sent_at,
    pc.received_at,
    pc.response_required,
    pc.response_due_by,
    pc.responded_at,
    pc.quoted_amount,
    pc.quoted_currency,
    pc.quoted_lead_time_days,
    pc.status,
    pc.created_at,
    pc.created_by_email,
    pc.tenant_id
   FROM procurement_communications pc
     JOIN procurement_orders po ON po.id = pc.order_id;
CREATE OR REPLACE VIEW public.v_procurement_vendor_directory AS
 SELECT vendor_name,
    array_agg(DISTINCT order_ref ORDER BY order_ref) AS orders,
    array_agg(DISTINCT vendor_contact_email) FILTER (WHERE vendor_contact_email IS NOT NULL) AS emails,
    array_agg(DISTINCT vendor_contact_url) FILTER (WHERE vendor_contact_url IS NOT NULL) AS urls,
    to_char(sum(estimated_total), '$9,999,999'::text) AS total_planned,
    count(*) AS order_count,
    array_agg(DISTINCT status) AS statuses
   FROM procurement_orders
  GROUP BY vendor_name
  ORDER BY (sum(estimated_total)) DESC NULLS LAST;
CREATE OR REPLACE VIEW public.v_rtk_fix_summary AS
 SELECT fix_type,
    measurement_purpose,
    count(*) AS fix_count,
    round(avg(horizontal_accuracy_m)::numeric, 3) AS avg_accuracy_m,
    round(min(horizontal_accuracy_m)::numeric, 3) AS best_accuracy_m,
    round(max(horizontal_accuracy_m)::numeric, 3) AS worst_accuracy_m,
    count(*) FILTER (WHERE horizontal_accuracy_m <= 0.05::double precision) AS sub_5cm_count,
    count(*) FILTER (WHERE horizontal_accuracy_m <= 0.10::double precision) AS sub_10cm_count,
    max(captured_at) AS last_capture_at
   FROM rtk_position_fixes
  GROUP BY fix_type, measurement_purpose
  ORDER BY (round(avg(horizontal_accuracy_m)::numeric, 3));
CREATE OR REPLACE VIEW public.v_active_peerings AS
 SELECT p.id,
    p.tenant_a_id,
    ta.name AS tenant_a_name,
    p.tenant_b_id,
    tb.name AS tenant_b_name,
    p.shared_scopes,
    p.authorised_by_email,
    p.authorised_at,
    p.expires_at,
        CASE
            WHEN p.expires_at IS NULL THEN 'permanent'::text
            WHEN p.expires_at < now() THEN 'expired'::text
            WHEN p.expires_at < (now() + '30 days'::interval) THEN 'expiring_soon'::text
            ELSE 'active'::text
        END AS expiry_status
   FROM tenant_peering_agreements p
     LEFT JOIN tenants ta ON ta.id = p.tenant_a_id
     LEFT JOIN tenants tb ON tb.id = p.tenant_b_id
  WHERE p.active = true AND p.revoked_at IS NULL
  ORDER BY p.authorised_at DESC;
CREATE OR REPLACE VIEW public.soc2_controls_by_criterion AS
 SELECT cc.code AS criterion_code,
    cc.name AS criterion_name,
    count(c.id) AS total,
    count(c.id) FILTER (WHERE c.implementation_status = 'implemented'::text) AS implemented,
    count(c.id) FILTER (WHERE c.implementation_status = 'in_progress'::text) AS in_progress,
    count(c.id) FILTER (WHERE c.implementation_status = 'planned'::text) AS planned,
    count(c.id) FILTER (WHERE c.automated = true) AS automated,
    round(count(c.id) FILTER (WHERE c.implementation_status = 'implemented'::text)::numeric / NULLIF(count(c.id), 0)::numeric * 100::numeric, 0) AS completion_pct
   FROM soc2_common_criteria cc
     LEFT JOIN soc2_controls c ON c.common_criteria_code = cc.code
  GROUP BY cc.code, cc.name, cc.sort_order
  ORDER BY cc.sort_order;
CREATE OR REPLACE VIEW public.v_ecosystem_backlog_open AS
 SELECT id,
    title,
    product,
    tier,
    importance,
    estimate_days,
    status,
    blocker,
    branch_or_pr,
    category,
    description,
    rationale,
    created_at
   FROM ecosystem_backlog
  WHERE status = ANY (ARRAY['pending'::text, 'in_progress'::text, 'blocked'::text])
  ORDER BY (
        CASE tier
            WHEN 'in_progress'::text THEN 1
            WHEN 'operational'::text THEN 2
            WHEN 'tier_1'::text THEN 3
            WHEN 'cross_cutting'::text THEN 4
            WHEN 'tier_2'::text THEN 5
            WHEN 'tier_3'::text THEN 6
            ELSE 9
        END), importance DESC, estimate_days;
CREATE OR REPLACE VIEW public.incident_impact AS
 SELECT ni.id AS incident_id,
    ni.type AS incident_type,
    ni.city,
    ni.title,
    ni.detail,
    ni.status,
    ni.eta,
    ni.affected_customers AS reported_affected,
    ni.created_at AS started_at,
    ni.resolved_at,
    count(DISTINCT cp.user_id) FILTER (WHERE cp.plan_status = 'active'::text AND (lower(cp.region) = lower(ni.city) OR lower(cp.address) ~~ (('%'::text || lower(ni.city)) || '%'::text))) AS customers_matched,
    count(DISTINCT pt.id) FILTER (WHERE pt.token IS NOT NULL) AS push_tokens_available,
        CASE
            WHEN ni.resolved_at IS NOT NULL THEN EXTRACT(epoch FROM ni.resolved_at - ni.created_at)::integer / 60
            ELSE EXTRACT(epoch FROM now() - ni.created_at)::integer / 60
        END AS duration_minutes
   FROM network_incidents ni
     LEFT JOIN customer_profiles cp ON cp.plan_status = 'active'::text AND (lower(cp.region) = lower(ni.city) OR lower(cp.address) ~~ (('%'::text || lower(ni.city)) || '%'::text))
     LEFT JOIN push_tokens pt ON pt.user_id = cp.user_id
  GROUP BY ni.id, ni.type, ni.city, ni.title, ni.detail, ni.status, ni.eta, ni.affected_customers, ni.created_at, ni.resolved_at;
CREATE OR REPLACE VIEW public.neighbourhood_impact AS
 SELECT id AS incident_id,
    title,
    detail,
    city,
    affected_parish,
    severity,
    status,
    eta,
    customer_summary,
    COALESCE(( SELECT count(DISTINCT cp.user_id) AS count
           FROM customer_profiles cp
          WHERE (cp.region ~~* (('%'::text || ni.affected_parish) || '%'::text) OR cp.address ~~* (('%'::text || ni.affected_parish) || '%'::text)) AND cp.plan_status = 'active'::text), 0::bigint)::integer AS neighbours_in_parish,
    COALESCE(( SELECT count(DISTINCT cp.user_id) AS count
           FROM customer_profiles cp
          WHERE cp.region ~~* (('%'::text || ni.city) || '%'::text) AND cp.plan_status = 'active'::text), 0::bigint)::integer AS neighbours_in_city,
    push_delivery_count AS neighbours_notified,
    created_at AS started_at,
    EXTRACT(epoch FROM COALESCE(resolved_at, now()) - created_at)::integer / 60 AS duration_minutes
   FROM network_incidents ni
  WHERE status = ANY (ARRAY['active'::text, 'investigating'::text, 'planned'::text]);
CREATE OR REPLACE VIEW public.job_packs_overview AS
 SELECT jp.id,
    jp.reference,
    jp.title,
    jp.description,
    jp.status,
    jp.priority,
    jp.parish,
    jp.location_lat,
    jp.location_lng,
    jp.address,
    jp.scheduled_date,
    jp.due_date,
    jp.completed_at,
    jp.created_by,
    jp.notes,
    jp.tags,
    jp.created_at,
    jp.updated_at,
    COALESCE(ta.tech_count, 0::bigint) AS assigned_technicians,
    COALESCE(ji.total_items, 0::bigint) AS total_items,
    COALESCE(ji.completed_items, 0::bigint) AS completed_items,
        CASE
            WHEN COALESCE(ji.total_items, 0::bigint) = 0 THEN 0::numeric
            ELSE round(COALESCE(ji.completed_items, 0::bigint)::numeric / ji.total_items::numeric * 100::numeric)
        END AS progress_pct
   FROM job_packs jp
     LEFT JOIN ( SELECT technician_assignments.job_pack_id,
            count(*) AS tech_count
           FROM technician_assignments
          GROUP BY technician_assignments.job_pack_id) ta ON ta.job_pack_id = jp.id
     LEFT JOIN ( SELECT job_pack_items.job_pack_id,
            count(*) AS total_items,
            count(*) FILTER (WHERE job_pack_items.status = 'complete'::text) AS completed_items
           FROM job_pack_items
          GROUP BY job_pack_items.job_pack_id) ji ON ji.job_pack_id = jp.id;
CREATE OR REPLACE VIEW public.network_asset_photos_unified AS
 SELECT ce.id::text AS photo_id,
    ce.network_asset_id AS asset_id,
    'chamber_evidence'::text AS source_table,
    ce.photo_url AS url,
    ce.photo_type AS category,
    ce.stage AS phase,
    ce.description AS caption,
    ce.technician_email AS captured_by,
    ce.captured_at,
    ce.latitude,
    ce.longitude,
    ce.opus_validated,
    ce.opus_score,
    ce.opus_notes,
    ce.work_order_id AS linked_task_id,
    NULL::text AS compass_heading
   FROM chamber_evidence ce
  WHERE ce.network_asset_id IS NOT NULL
UNION ALL
 SELECT fe.id::text AS photo_id,
    fe.network_asset_id AS asset_id,
    'field_evidence'::text AS source_table,
    COALESCE(fe.compressed_url, fe.file_url) AS url,
    fe.evidence_type AS category,
    fe.phase,
    NULL::text AS caption,
    fe.technician_email AS captured_by,
    fe.captured_at,
    fe.gps_lat AS latitude,
    fe.gps_lng AS longitude,
    fe.opus_analysis IS NOT NULL AS opus_validated,
    NULL::double precision AS opus_score,
    fe.opus_analysis::text AS opus_notes,
    fe.work_order_id AS linked_task_id,
    NULL::text AS compass_heading
   FROM field_evidence fe
  WHERE fe.network_asset_id IS NOT NULL
UNION ALL
 SELECT pe.id::text AS photo_id,
    pe.network_asset_id AS asset_id,
    'photo_evidence'::text AS source_table,
    pe.image_url AS url,
    pe.category,
    NULL::text AS phase,
    pe.caption,
    NULL::text AS captured_by,
    pe.captured_at,
    pe.latitude,
    pe.longitude,
    pe.opus_analysis IS NOT NULL AS opus_validated,
    NULL::double precision AS opus_score,
    pe.opus_analysis AS opus_notes,
    pe.job_id AS linked_task_id,
    pe.compass_heading::text AS compass_heading
   FROM photo_evidence pe
  WHERE pe.network_asset_id IS NOT NULL
UNION ALL
 SELECT hp.id::text AS photo_id,
    hp.network_asset_id AS asset_id,
    'hs_photos'::text AS source_table,
    hp.photo_url AS url,
    hp.photo_type AS category,
    NULL::text AS phase,
    hp.caption,
    hp.taken_by AS captured_by,
    hp.taken_at AS captured_at,
    hp.latitude,
    hp.longitude,
    NULL::boolean AS opus_validated,
    NULL::double precision AS opus_score,
    NULL::text AS opus_notes,
    COALESCE(hp.assessment_id, hp.incident_id) AS linked_task_id,
    NULL::text AS compass_heading
   FROM hs_photos hp
  WHERE hp.network_asset_id IS NOT NULL;
CREATE OR REPLACE VIEW public.network_asset_photo_counts AS
 SELECT asset_id,
    count(*) AS total_photos,
    count(*) FILTER (WHERE source_table = 'chamber_evidence'::text) AS chamber_photos,
    count(*) FILTER (WHERE source_table = 'field_evidence'::text) AS field_photos,
    count(*) FILTER (WHERE source_table = 'photo_evidence'::text) AS job_photos,
    count(*) FILTER (WHERE source_table = 'hs_photos'::text) AS hs_photos,
    count(*) FILTER (WHERE opus_validated = true) AS opus_validated,
    max(captured_at) AS latest_photo_at,
    array_agg(DISTINCT phase) FILTER (WHERE phase IS NOT NULL) AS phases_captured
   FROM network_asset_photos_unified
  GROUP BY asset_id;
CREATE OR REPLACE VIEW public.v_predictive_lookback_kpi AS
 WITH bucketed AS (
         SELECT v_predicted_incidents.incident_id,
            min(
                CASE v_predicted_incidents.prediction_outcome
                    WHEN 'caught_acted'::text THEN 1
                    WHEN 'caught_unacted'::text THEN 2
                    WHEN 'caught_dismissed'::text THEN 3
                    WHEN 'missed'::text THEN 4
                    ELSE 5
                END) AS best_rank
           FROM v_predicted_incidents
          GROUP BY v_predicted_incidents.incident_id
        )
 SELECT count(*) AS total_incidents,
    sum(
        CASE
            WHEN best_rank = 1 THEN 1
            ELSE 0
        END) AS caught_acted,
    sum(
        CASE
            WHEN best_rank = 2 THEN 1
            ELSE 0
        END) AS caught_unacted,
    sum(
        CASE
            WHEN best_rank = 3 THEN 1
            ELSE 0
        END) AS caught_dismissed,
    sum(
        CASE
            WHEN best_rank = 4 THEN 1
            ELSE 0
        END) AS missed,
        CASE
            WHEN count(*) = 0 THEN NULL::numeric
            ELSE round(sum(
            CASE
                WHEN best_rank = ANY (ARRAY[1, 2, 3]) THEN 1
                ELSE 0
            END)::numeric / count(*)::numeric * 100::numeric, 1)
        END AS catch_rate_pct,
        CASE
            WHEN count(*) = 0 THEN NULL::numeric
            ELSE round(sum(
            CASE
                WHEN best_rank = 1 THEN 1
                ELSE 0
            END)::numeric / count(*)::numeric * 100::numeric, 1)
        END AS caught_and_acted_rate_pct
   FROM bucketed;
CREATE OR REPLACE VIEW public.v_predictive_lead_time_distribution AS
 SELECT count(*) AS caught_count,
    round(avg(lead_time_hours), 1) AS avg_lead_time_hours,
    round(min(lead_time_hours), 1) AS min_lead_time_hours,
    round(max(lead_time_hours), 1) AS max_lead_time_hours,
    round(percentile_cont(0.5::double precision) WITHIN GROUP (ORDER BY (lead_time_hours::double precision))::numeric, 1) AS median_lead_time_hours,
    round(percentile_cont(0.9::double precision) WITHIN GROUP (ORDER BY (lead_time_hours::double precision))::numeric, 1) AS p90_lead_time_hours,
    sum(
        CASE
            WHEN lead_time_hours <= 6::numeric THEN 1
            ELSE 0
        END) AS caught_within_6h,
    sum(
        CASE
            WHEN lead_time_hours > 6::numeric AND lead_time_hours <= 24::numeric THEN 1
            ELSE 0
        END) AS caught_6h_to_1d,
    sum(
        CASE
            WHEN lead_time_hours > 24::numeric AND lead_time_hours <= 168::numeric THEN 1
            ELSE 0
        END) AS caught_1d_to_7d,
    sum(
        CASE
            WHEN lead_time_hours > 168::numeric AND lead_time_hours <= 720::numeric THEN 1
            ELSE 0
        END) AS caught_7d_to_30d,
    sum(
        CASE
            WHEN lead_time_hours > 720::numeric THEN 1
            ELSE 0
        END) AS caught_30d_plus
   FROM v_predicted_incidents
  WHERE lead_time_hours IS NOT NULL AND prediction_outcome <> 'missed'::text;
CREATE OR REPLACE VIEW public.v_incidents_with_duration AS
 SELECT id,
    title,
    description,
    severity,
    status,
    detection_source,
    started_at,
    acknowledged_at,
    mitigated_at,
    resolved_at,
    root_cause,
    affected_systems,
    customer_impact_count,
    revenue_impact_usd,
    pir_artifact_id,
    pir_completed_at,
    tenant_id,
    created_by,
    created_at,
    updated_at,
    started_at + '48:00:00'::interval AS pir_due_at,
    EXTRACT(epoch FROM COALESCE(resolved_at, mitigated_at, now()) - started_at)::integer / 60 AS duration_minutes,
    pir_completed_at IS NULL AND now() > (started_at + '48:00:00'::interval) AS pir_overdue
   FROM incidents i;
CREATE OR REPLACE VIEW public.v_web_vitals_daily AS
 SELECT date_trunc('day'::text, measured_at) AS day,
    source_product,
    page_path,
    metric_name,
    count(*) AS sample_count,
    percentile_cont(0.50::double precision) WITHIN GROUP (ORDER BY metric_value) AS p50,
    percentile_cont(0.75::double precision) WITHIN GROUP (ORDER BY metric_value) AS p75,
    percentile_cont(0.95::double precision) WITHIN GROUP (ORDER BY metric_value) AS p95,
    count(*) FILTER (WHERE metric_rating = 'good'::text) AS good_count,
    count(*) FILTER (WHERE metric_rating = 'needs-improvement'::text) AS needs_improvement_count,
    count(*) FILTER (WHERE metric_rating = 'poor'::text) AS poor_count
   FROM web_vitals
  WHERE measured_at >= (now() - '90 days'::interval)
  GROUP BY (date_trunc('day'::text, measured_at)), source_product, page_path, metric_name;

