DROP TRIGGER IF EXISTS trg_wo_predictive_drafted_webhook ON public.work_orders;
CREATE TRIGGER trg_wo_predictive_drafted_webhook AFTER INSERT ON public.work_orders FOR EACH ROW EXECUTE FUNCTION trg_wo_predictive_drafted_emit();
DROP TRIGGER IF EXISTS trg_wo_predictive_escalated_webhook ON public.work_orders;
CREATE TRIGGER trg_wo_predictive_escalated_webhook AFTER UPDATE OF priority ON public.work_orders FOR EACH ROW EXECUTE FUNCTION trg_wo_predictive_escalated_emit();
DROP TRIGGER IF EXISTS trg_wo_window_close ON public.work_orders;
CREATE TRIGGER trg_wo_window_close AFTER UPDATE OF status ON public.work_orders FOR EACH ROW EXECUTE FUNCTION trg_wo_cancel_window_on_close();

-- Event triggers
DROP EVENT TRIGGER IF EXISTS ensure_rls;
CREATE EVENT TRIGGER ensure_rls ON ddl_command_end EXECUTE FUNCTION public.rls_auto_enable();

